const stdout = ($input.first().json.stdout || '').trim();
let research = {};
let research_status = 'ok';
try {
  research = stdout ? JSON.parse(stdout) : {};
  if (!research || typeof research !== 'object' || Object.keys(research).length === 0) research_status = 'empty';
} catch (e) {
  research = {};
  research_status = 'failed';
}
const job = $('Webhook: jhound-apply').first().json.body;
let domain = research.domain || job.company_domain || '';
if (!domain && research.website) {
  domain = research.website.replace(/^https?:\/\//, '').split('/')[0].replace(/^www\./, '');
}
const jd = [job.job_description, job.description, job.snippet, job.summary].filter(Boolean).join('\n');
const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const SKIP_DOMAINS = /@(example|test|sentry|yourcompany|noreply|no-reply|donotreply|do-not-reply|users\.noreply\.github|sentry\.io|wixpress|wix|mailchimp|getresponse)\./i;
const SKIP_LOCAL = /^(noreply|no-reply|donotreply|do-not-reply|postmaster|mailer-daemon|notifications?|support|info|admin|webmaster|abuse|privacy|legal|sales|marketing)@/i;
let jd_email = null;
if (jd) {
  const matches = (jd.match(EMAIL_RE) || []).filter(e => !SKIP_DOMAINS.test(e) && !SKIP_LOCAL.test(e));
  if (matches.length) jd_email = matches[0];
}
return [{ json: { job, research, research_status, company_domain: domain, jd_email } }];
